// ═══ Diff Tests — computeDiffs ═══
// Tests for diff detection between sheet data and system data.
// Generated by AREF agent.

describe('SAFE_FIELDS classification', () => {
  const SAFE_FIELDS_RECEIVED = ['Hold', 'Holds', 'Battery', 'ULD']
  const SAFE_FIELDS_PENDING = ['Hold', 'Holds', 'Battery', 'Docs/Drive', 'Pickup', 'Ready', 'LFD', 'ULD']

  test('Hold (singular) should be in SAFE_FIELDS for received AWBs', () => {
    expect(SAFE_FIELDS_RECEIVED).toContain('Hold')
  })

  test('Holds (plural) should be in SAFE_FIELDS for received AWBs', () => {
    expect(SAFE_FIELDS_RECEIVED).toContain('Holds')
  })

  test('PCS should NOT be in SAFE_FIELDS for received AWBs', () => {
    expect(SAFE_FIELDS_RECEIVED).not.toContain('PCS')
  })

  test('Vuelo should NOT be in SAFE_FIELDS', () => {
    expect(SAFE_FIELDS_RECEIVED).not.toContain('Vuelo')
  })
})

describe('same-day hold application', () => {
  test('holdDiffs should be separated from otherDiffs in same-day branch', () => {
    const diffs = [
      { field: 'Hold', new_value: 'HOLD', old_value: 'NO HOLD' },
      { field: 'PCS', new_value: '100', old_value: '80' },
      { field: 'Holds', new_value: '3 holds', old_value: '0 holds' },
    ]
    const holdDiffs = diffs.filter(d => d.field === 'Hold' || d.field === 'Holds')
    const otherDiffs = diffs.filter(d => d.field !== 'Hold' && d.field !== 'Holds')

    expect(holdDiffs).toHaveLength(2)
    expect(otherDiffs).toHaveLength(1)
    expect(otherDiffs[0].field).toBe('PCS')
  })

  test('only-hold diffs on same-day should NOT generate alert', () => {
    const diffs = [
      { field: 'Hold', new_value: 'HOLD', old_value: 'NO HOLD' },
    ]
    const otherDiffs = diffs.filter(d => d.field !== 'Hold' && d.field !== 'Holds')
    expect(otherDiffs).toHaveLength(0) // No alert needed
  })
})
